import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sigmoid_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor sigmoid_forward(torch::Tensor x);
"""

sigmoid_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void __launch_bounds__(256, 6) sigmoid_kernel_cute(const float* __restrict__ X,
                                    float* __restrict__ Y,
                                    int64_t N)
{
  using Vec = float4;

  const int64_t nvec = N >> 2;

  Tensor mXv = make_tensor(make_gmem_ptr(reinterpret_cast<const Vec*>(X)), make_shape(nvec));
  Tensor mYv = make_tensor(make_gmem_ptr(reinterpret_cast<Vec*>(Y)),       make_shape(nvec));

  const int64_t tid    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  const int64_t stride = (int64_t)gridDim.x * blockDim.x;

  auto sig4 = [](Vec v) {
    Vec r;
    r.x = 1.0f / (1.0f + __expf(-v.x));
    r.y = 1.0f / (1.0f + __expf(-v.y));
    r.z = 1.0f / (1.0f + __expf(-v.z));
    r.w = 1.0f / (1.0f + __expf(-v.w));
    return r;
  };
  // Occupancy boost via register-pressure cap: at 44 regs/thread the compiler
  // allocates 48 registers, allowing only 5 CTAs/SM (1280/1536 threads = 83.3%
  // theoretical occupancy, matching Nsight). __launch_bounds__(256, 6) caps
  // allocation at 40 regs/thread so 6 CTAs are resident per SM (100% theoretical
  // occupancy). For this purely DRAM-bound streaming kernel, the extra resident
  // warps increase the number of in-flight float4 loads, closing the
  // theoretical-vs-achieved occupancy gap (73.1%) flagged by the profiler and
  // keeping DRAM saturated. The occupancy-driven wave-exact grid below
  // automatically picks up the new 6-blocks/SM residency.
  // Streaming cache hints: this kernel is purely DRAM-bound (~88% DRAM
  // throughput) with zero data reuse, so use __ldcs/__stcs (evict-first
  // streaming loads/stores). The default caching policy lets read-once /
  // write-once data pollute L2 and delays writebacks; the streaming
  // policy marks both the float4 loads and stores as evict-first so the
  // memory subsystem can drain writes back-to-back and keep DRAM busy,
  // raising effective bandwidth utilization for this streaming kernel.
  int64_t i = tid;
  const int64_t stride4 = stride << 2;
  for (; i + 3 * stride < nvec; i += stride4) {
    Vec v0 = __ldcs(&mXv(i));
    Vec v1 = __ldcs(&mXv(i + stride));
    Vec v2 = __ldcs(&mXv(i + 2 * stride));
    Vec v3 = __ldcs(&mXv(i + 3 * stride));
    __stcs(&mYv(i),              sig4(v0));
    __stcs(&mYv(i + stride),     sig4(v1));
    __stcs(&mYv(i + 2 * stride), sig4(v2));
    __stcs(&mYv(i + 3 * stride), sig4(v3));
  }
  for (; i < nvec; i += stride) {
    __stcs(&mYv(i), sig4(__ldcs(&mXv(i))));
  }

  if (blockIdx.x == 0 && threadIdx.x == 0) {
    Tensor mX = make_tensor(make_gmem_ptr(X), make_shape(N));
    Tensor mY = make_tensor(make_gmem_ptr(Y), make_shape(N));
    for (int64_t i = (nvec << 2); i < N; ++i) {
      float v = mX(i);
      mY(i) = 1.0f / (1.0f + __expf(-v));
    }
  }
}

torch::Tensor sigmoid_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  const int64_t N = x_c.numel();
  auto y = torch::empty_like(x_c);

  if (N == 0) {
    return y;
  }

  const float* x_ptr = x_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();

  constexpr int threads = 256;  // Larger CTA: fewer blocks to schedule, better load balance across warps, raises achieved occupancy for this DRAM-bound streaming kernel
  const int64_t nvec = N >> 2;
  int64_t wanted_blocks = (nvec + (int64_t)threads * 4 - 1) / ((int64_t)threads * 4);  // 4 float4 per thread
  if (wanted_blocks <= 0) wanted_blocks = 1;  // handles N < 4 tails
  // Wave-exact persistent grid: query the occupancy API for the number of
  // 256-thread CTAs that can be resident per SM, then launch exactly one
  // full wave (SMs * blocksPerSM). Nsight showed the previous fixed cap
  // (SMs * 8) produced 1 full wave plus a partial wave of 256 CTAs, which
  // can account for up to ~50% of runtime for this DRAM-bound streaming
  // kernel. Matching the grid to the exact resident wave removes the tail
  // wave and the load imbalance that held achieved occupancy at ~84%; the
  // grid-stride loop covers all remaining data.
  static int max_blocks = 0;
  if (max_blocks == 0) {
    int dev = 0, sms = 0, blocks_per_sm = 0;
    cudaGetDevice(&dev);
    cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks_per_sm, sigmoid_kernel_cute, threads, 0);
    if (blocks_per_sm <= 0) blocks_per_sm = 8;
    max_blocks = sms > 0 ? sms * blocks_per_sm : 1024;
  }
  const int blocks = wanted_blocks > (int64_t)max_blocks ? max_blocks : (int)wanted_blocks;

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  sigmoid_kernel_cute<<<blocks, threads, 0, stream>>>(x_ptr, y_ptr, N);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE sigmoid launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

sigmoid_ext = load_inline(
    name="cute_sigmoid_inline",
    cpp_sources=sigmoid_cpp_decl,
    cuda_sources=sigmoid_cuda_src,
    functions=["sigmoid_forward"],
    extra_cflags=["-O3", "-std=c++17"],
    extra_cuda_cflags=["-O3", "-std=c++17"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
